const inp = $workflow.input || {};
const src = inp.requestSource || 'PolicyInForceCheck';
const scenario = inp.scenario || 'Standard';
const claimReference = inp.claimReference || '';

const SCENARIOS = {
  Standard: { policyNumber: 'PIC-ML-204471', coverType: 'Motor Third Party Liability - Standard', policyLimitIndemnity: 5000000, policyLimitCosts: 250000, notificationDelayDays: 0, liabilityCoverInForce: true },
  Displaced: { policyNumber: 'PIC-ML-118820', coverType: 'Motor Third Party Liability - Enhanced', policyLimitIndemnity: 10000000, policyLimitCosts: 500000, notificationDelayDays: 0, liabilityCoverInForce: true },
  Underinsured: { policyNumber: 'PIC-ML-337512', coverType: 'Motor Third Party Liability - Standard', policyLimitIndemnity: 1000000, policyLimitCosts: 100000, notificationDelayDays: 0, liabilityCoverInForce: true },
  Investigated: { policyNumber: 'PIC-ML-552901', coverType: 'Employers Liability - Standard', policyLimitIndemnity: 5000000, policyLimitCosts: 200000, notificationDelayDays: 0, liabilityCoverInForce: true },
  Declined: { policyNumber: 'PIC-ML-771034', coverType: 'Motor Third Party Liability - Standard', policyLimitIndemnity: 5000000, policyLimitCosts: 250000, notificationDelayDays: 75, liabilityCoverInForce: false },
  Reopened: { policyNumber: 'PIC-ML-990112', coverType: 'Motor Third Party Liability - Standard', policyLimitIndemnity: 5000000, policyLimitCosts: 250000, notificationDelayDays: 0, liabilityCoverInForce: true }
};

const s = SCENARIOS[scenario] || SCENARIOS.Standard;

const out = {
  policyNumber: '',
  coverType: '',
  policyLimitIndemnity: 0,
  policyLimitCosts: 0,
  notificationDelayDays: 0,
  liabilityCoverInForce: false,
  explanation: ''
};

if (src === 'PolicyInForceCheck') {
  out.policyNumber = s.policyNumber;
  out.coverType = s.coverType;
  out.policyLimitIndemnity = s.policyLimitIndemnity;
  out.policyLimitCosts = s.policyLimitCosts;
  out.notificationDelayDays = s.notificationDelayDays;
  out.liabilityCoverInForce = s.liabilityCoverInForce;
  out.explanation = 'Policy ' + s.policyNumber + ' confirmed in force for claim ' + (claimReference || '(unspecified)') + ' with ' + s.coverType + ' cover in place at the date of the accident.';
} else {
  out.explanation = 'Unrecognised requestSource: ' + src + '.';
}

return out;
